import studentIndex from "@/data/students.index.json";
import { migrateDemoData } from "@/lib/dataset/migrate";

// Runs on import, before any page reads saved data keyed by student id.
migrateDemoData();

/**
 * Admin-side view of the unified dataset (see data/DATASET.md).
 *
 * `data/students.index.json` is generated by `npm run generate:data` from the same records the student portal
 * reads, so ids, names and scores always agree between the admin and student dashboards. Only this slim summary
 * is bundled; full per-student records are fetched on demand by the student portal.
 */
export type StudentProfile = {
  id: string;
  name: string;
  department: string;
  year: string;
  attendance: number;
  academicScore: number;
  assignmentCompletion: number;
  skillsScore: number;
  placementScore: number;
  engagementScore: number;
  successScore: number;
  risk: "High" | "Medium" | "Low";
  riskReasons: string[];
  rollNo: string;
  branchCode: string;
  section: string;
  mentorId: string;
  mentorName: string;
  cgpa: number;
  activeBacklogs: number;
  semester: number;
  /** Mean marks per semester, index 0 = semester 1. */
  semesterScores: number[];
  /** [subject code, marks] pairs of the latest semester. */
  subjectScores: [string, number][];
  /** Placement components (0-100). */
  placement: { technical: number; aptitude: number; communication: number; interview: number };
  /** Attendance % per semester, index 0 = semester 1. */
  semesterAttendance: number[];
  /** Lectures attended / held in the latest semester. */
  lectures: { attended: number; total: number };
  /** Technical (DSA, Web Dev, DBMS, Python, Java, C, SQL) then soft (Communication, Teamwork, Problem Solving, Leadership, Time Management) scores. */
  skillVector: number[];
};

export const studentProfiles: StudentProfile[] = studentIndex as StudentProfile[];

export const studentDepartments = Array.from(new Set(studentProfiles.map((student) => student.department)));
